      "procurement_payment": [
        {
          "text": "UAE: electronic invoicing is being implemented in phases. Have the finance owner establish the entity's applicable implementation and preparation dates from the current FTA notice.",
          "kind": "legal",
          "source_ids": [
            "I:AE-INVOICE"
          ],
          "jurisdictions": [
            "AE"
          ],
          "applies_when": "For persons and transactions subject to the electronic invoicing regime. Do not assume every business already has the same deadline."
        },
        {
          "text": "Saudi Arabia: ZATCA distinguishes invoice generation requirements from integration requirements introduced in notified waves. Ask finance which phase and notice apply.",
          "kind": "legal",
          "source_ids": [
            "I:SA-INVOICE"
          ],
          "jurisdictions": [
            "SA"
          ],
          "applies_when": "For taxpayers and invoices within the electronic invoicing rules; nonresident and other exclusions require checking."
        }
      ],
      "data_privacy": [
        {
          "text": "UAE: Federal Decree Law 45 of 2021 on personal data has exclusions, including certain sector data and free zones with their own privacy laws. Identify the entity, data and legal regime before choosing controls.",
          "kind": "legal",
          "source_ids": [
            "I:AE-PDPL"
          ],
          "jurisdictions": [
            "AE"
          ],
          "applies_when": "Apply only after checking Article 2 exclusions and the relevant implementation instruments. Do not infer DIFC or ADGM from a city name."
        },
        {
          "text": "Saudi Arabia: the Personal Data Protection Law and the Regulation on Personal Data Transfer outside the Kingdom require an applicable transfer basis and protection review. Map overseas processing before agreeing the contract.",
          "kind": "legal",
          "source_ids": [
            "I:SA-TRANSFER"
          ],
          "jurisdictions": [
            "SA"
          ],
          "applies_when": "For personal data transfers within the Saudi regime. This is not a blanket requirement to keep every type of data in Saudi Arabia."
        },
        {
          "text": "For Qatar, identify whether Law No. 13 of 2016 on Protecting Personal Data Privacy governs the planned electronic processing. Record the controller, processor and purpose before selecting the contract and access checks.",
          "kind": "legal",
          "source_ids": [
            "I:QA-PDP"
          ],
          "jurisdictions": [
            "QA"
          ],
          "applies_when": "Processing within this law's scope; confirm the entity's legal regime before applying it"
        },
        {
          "text": "Bahrain has Law No. 30 of 2018 with Respect to Personal Data Protection Law. Identify the controller and processor and have the privacy reviewer confirm the current processing and transfer conditions for the proposed workflow.",
          "kind": "legal",
          "source_ids": [
            "I:BH-PDP"
          ],
          "jurisdictions": [
            "BH"
          ],
          "applies_when": "Personal data processing governed by Bahrain's law; current implementing decisions must be checked"
        },
        {
          "text": "In Oman, use the Personal Data Protection Law with the amendments in Royal Decree 68/2026. The amendments affect scope, exemptions and automated processing. Ask the privacy reviewer to confirm which provisions govern the data flow before using an older permit or consent checklist.",
          "kind": "legal",
          "source_ids": [
            "I:OM-PDP"
          ],
          "jurisdictions": [
            "OM"
          ],
          "applies_when": "Oman personal data processing within the amended law's scope"
        },
        {
          "text": "For Kuwait, check the applicable scope of CITRA's Data Privacy Protection Regulation issued by Decision 26 of 2024. That decision replaced the regulation under Decision 42 of 2021, so an old 2021 checklist is not a sufficient basis for the review.",
          "kind": "legal",
          "source_ids": [
            "I:KW-PDP"
          ],
          "jurisdictions": [
            "KW"
          ],
          "applies_when": "Only where the current CITRA regulation covers the entity and service; scope requires confirmation"
        }
      ],
